                        side + 2 * (column + face_row * path->width_cells);
                    if (side == 0)
                    {
                        facequads[face_offset].header_word = 0;
                        facequads[face_offset].vertex_0 =
                            column + face_row * ((unsigned short)path->width_cells + 1);
