void cRPath::initialize_supertramp_path_template_pair(float length, int width_cells_,
                                                      bool side_exit, char *texture_a,
                                                      char *texture_b,
                                                      char *unused_texture,
                                                      char *cap_texture)
{
    kind = PATH_TEMPLATE_KIND_SUPERTRAMP;
    is_mirrored_x = 0;
    side_exit_mode = 0;
    width_cells = width_cells_;

